import { useState, useEffect } from 'react';
import Link from 'next/link';
import styles from '@/app/assets/scss/web/Estilo.module.scss';


export default function BentoGrid() {
    const [noticias, setNoticias] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetch('http://localhost:8000/backend/api/handlers/pagina_principal.php?bento=true')
            .then(response => response.json())
            .then(res => {
                if (res.success && res.data && res.data.length > 0) {
                    setNoticias(res.data);
                }
                setLoading(false);
            })
            .catch(error => {
                console.error('Error fetching noticia:', error);
                setLoading(false);
            });
    }, []);

    if (loading) return <div className={styles.loading}>Cargando panel...</div>;
    if (noticias.length === 0) return <div className={styles.error}>No hay noticias disponibles.</div>;

    return (
        <section className={`${styles.bentoGrid}`}>
                {noticias.slice(0, 4).map((noticia, index) => {
                    const imageUrl = noticia.path 
                    ? `/img/web/${noticia.path}/img_${noticia.path}.png` 
                    : '/img/web/logo_tierra.png';

                    return (
                        <article key={noticia.id} className={styles[`noticia${index + 1}`]} style={{ '--bg-noticia': `url(${imageUrl})` }}>
                            <Link href={`/noticia/${noticia.id}`}>
                                <h3>{noticia.titulo}</h3>
                                <p>
                                    <span>{noticia.bandera}</span> 
                                    {noticia.nombre_pais?.toUpperCase()}
                                </p>
                            </Link>
                    </article>
                    );
                })}
        </section>
    )
}